<template><section class="demo-shell"><h2>文件演示</h2><p class="note">仅在本页面读取文件，不会上传。接受 txt、csv、json，最大 1 MiB。请使用自行构造的演示文件。</p><form action="" method="post" @submit.prevent="submit" class="native-form"><label v-if="withForm" for="document-name">演示文档名称<input id="document-name" name="documentName" v-model="documentName" :required="withForm" maxlength="60"></label><label for="demo-file">演示文件<input id="demo-file" ref="fileInput" name="demoFile" type="file" accept=".txt,.csv,.json" @change="change"></label><div class="actions"><el-button native-type="submit">校验文件</el-button><el-button native-type="button" @click="reset">清空文件</el-button></div></form><p role="status" class="summary">{{notice}}</p><dl v-if="info"><dt>文件名</dt><dd>{{info.name}}</dd><dt>字节数</dt><dd>{{info.size}}</dd></dl><pre v-if="preview" class="output" aria-label="本地文件预览">{{preview}}</pre></section></template><script>import options from "./demo.mjs";export default options;</script><style src="./style.css"></style>
